var datum, txt;

// Beschreibe diese Funktion …
async function Logfile(datum, txt) {
    if (getState('0_userdata.0.go-e_V4.DebugAktiv_V4').val) {
      require('fs').appendFileSync('/opt/iobroker/log/' + datum + ' - go_E_V4.log', formatDate(new Date(), "hh:mm:ss") + " \t" + txt + "\n");}
}


// ------->>>> Phasenerkennung
// 57 = 1P, 63 = 3P Auto laden, 56 = kein Auto
schedule("*/5 * * * * *", async () => {
  setState('0_userdata.0.go-e-phases_V4.L1_Zuleitung_V4' /* L1_Zuleitung_V4 */, (Math.floor(getState('go-e.1.phases').val / 8) % 2 === 1));
  setState('0_userdata.0.go-e-phases_V4.L2_Zuleitung_V4' /* L2_Zuleitung_V4 */, (Math.floor(getState('go-e.1.phases').val / 16) % 2 === 1));
  setState('0_userdata.0.go-e-phases_V4.L3_Zuleitung_V4' /* L3_Zuleitung_V4 */, (Math.floor(getState('go-e.1.phases').val / 32) % 2 === 1));
  setState('0_userdata.0.go-e-phases_V4.L1_Auto_V4' /* L1_Auto_V4 */, (Math.floor(getState('go-e.1.phases').val / 1) % 2 === 1));
  setState('0_userdata.0.go-e-phases_V4.L2_Auto_V4' /* L2_Auto_V4 */, (Math.floor(getState('go-e.1.phases').val / 2) % 2 === 1));
  setState('0_userdata.0.go-e-phases_V4.L3_Auto_V4' /* L3_Auto_V4 */, (Math.floor(getState('go-e.1.phases').val / 4) % 2 === 1));
  // ---->>> Phasendefinition
  if (getState('0_userdata.0.go-e-phases_V4.L1_Auto_V4').val && (getState('0_userdata.0.go-e-phases_V4.L2_Auto_V4').val && getState('0_userdata.0.go-e-phases_V4.L3_Auto_V4').val) && (!getState('0_userdata.0.go-e_V4.3P_V4').val)) {
    setState('0_userdata.0.go-e_V4.1P_V4' /* 1P_V4 */, false);
    setState('0_userdata.0.go-e_V4.3P_V4' /* 3P_V4 */, true);
    if (getState('0_userdata.0.go-e_V4.minPV_V4').val != 4500) {
      setState('0_userdata.0.go-e_V4.minPV_V4' /* minPVÜberschuss_V4 */, 4500);
    }
    await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), 'Phasen / -------->>> V4 3P Ladung erkannt');
    console.info('1P false, 3P true');
  } else if (getState('0_userdata.0.go-e-phases_V4.L1_Auto_V4').val && (!getState('0_userdata.0.go-e-phases_V4.L2_Auto_V4').val && !getState('0_userdata.0.go-e-phases_V4.L3_Auto_V4').val) && (!getState('0_userdata.0.go-e_V4.1P_V4').val)) {
    setState('0_userdata.0.go-e_V4.1P_V4' /* 1P_V4 */, true);
    setState('0_userdata.0.go-e_V4.3P_V4' /* 3P_V4 */, false);
    if (getState('0_userdata.0.go-e_V4.minPV_V4').val != 1500) {
      setState('0_userdata.0.go-e_V4.minPV_V4' /* minPVÜberschuss_V4 */, 1500);
    }
    await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), 'Phasen / -------->>> V4 1P Ladung erkannt');
    console.info('1P true, 3P false');
  }
  if (getState('0_userdata.0.go-e_V4.1P_V4').val) {
    setState('0_userdata.0.go-e_V4.minW_V4' /* minWatt_V4 */, (getState('0_userdata.0.go-e_V4.minA_1P_V4').val * 230));
  } else if (getState('0_userdata.0.go-e_V4.3P_V4').val) {
    setState('0_userdata.0.go-e_V4.minW_V4' /* minWatt_V4 */, (getState('0_userdata.0.go-e_V4.minA_3P_V4').val * 3 * 230));
  }
});
// manuelle Phasenumschaltung
on({ id: '0_userdata.0.go-e-phases_V4.Phasenumschaltung_V4' /* Phasenumschaltung_V4 */, val: true, ack: false }, async (obj) => {
  let value = obj.state.val;
  let oldValue = obj.oldState.val;
  console.info('manuelle Phasenumschaltung');
  if (getState('go-e.1.unlocked_by').val == 0) {
    if (getState('0_userdata.0.go-e_V4.1P_V4').val) {
      httpGet('http://192.168.11.21/api/set?psm=2', { timeout: 2000, responseType: 'text' }, async (err, response) => {
      });
      setState('0_userdata.0.go-e_V4.1P_V4' /* 1P_V4 */, false);
      setState('0_userdata.0.go-e_V4.3P_V4' /* 3P_V4 */, true);
      console.info('manuelle Umschaltung auf 2 Phase');
    } else if (getState('0_userdata.0.go-e_V4.3P_V4').val) {
      httpGet('http://192.168.11.21/api/set?psm=1', { timeout: 2000, responseType: 'text' }, async (err, response) => {
      });
      setState('0_userdata.0.go-e_V4.1P_V4' /* 1P_V4 */, true);
      setState('0_userdata.0.go-e_V4.3P_V4' /* 3P_V4 */, false);
      console.info('manuelle Umschaltung auf 1 Phase');
    }
    setStateDelayed('0_userdata.0.go-e-phases_V4.Phasenumschaltung_V4' /* Phasenumschaltung_V4 */, false, 2000, false);
  }
});
// automatische Phasenumschaltung
schedule("* * * * *", async () => {
  if (getState('go-e.1.unlocked_by').val == 0) {
    // Umschaltung auf 1P
    if ((getState('go-e.1.car').val >= 1) && (getState('alias.0.Fronius.AC-Power').val <= 5000) && (getState('go-e.1.energy.power').val == 0) && getState('0_userdata.0.go-e_V4.3P_V4').val && getState('0_userdata.0.go-e_V4.AUTO_V4').val) {
      httpGet('http://192.168.11.21/api/set?psm=1', { timeout: 2000, responseType: 'text' }, async (err, response) => {
      });
      setState('0_userdata.0.go-e_V4.1P_V4' /* 1P_V4 */, true);
      setState('0_userdata.0.go-e_V4.3P_V4' /* 3P_V4 */, false);
      setState('go-e.1.amperePV' /* Ampere for PWM (amx) (FW > 033 required) */, parseFloat(getState('0_userdata.0.go-e_V4.minA_1P_V4').val));
      if (getState('0_userdata.0.go-e_V4.minPV_V4').val > 1250) {
        setState('0_userdata.0.go-e_V4.minPV_V4' /* minPVÜberschuss_V4 */, 1250);
      }
      await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), 'Phasen / -------->>> Umschaltung auf 1P');
      sendTo('telegram.0', 'send', {
        text: 'go-ECharger V4 auf 1P Ladung umgeschaltet',
      });
      console.log('telegram: ' + 'go-ECharger V4 auf 1P Ladung umgeschaltet');
    }
    // Umschaltung auf 3P
    if ((getState('go-e.1.allow_charging').val && (getState('go-e.1.amperePV').val == getState('0_userdata.0.go-e_V4.maxA_1P_V4').val) && (getState('alias.0.EM24 Hall Grid.PV_Überschuss').val >= 3500) && (getState('alias.0.Fronius.AC-Power').val >= 6000) && getState('0_userdata.0.go-e_V4.1P_V4').val && getState('0_userdata.0.go-e_V4.AUTO_V4').val) || ((getState('go-e.1.car').val == 1) && (getState('alias.0.Fronius.AC-Power').val >= 6000) && getState('0_userdata.0.go-e_V4.1P_V4').val && getState('0_userdata.0.go-e_V4.AUTO_V4').val)) {
      httpGet('http://192.168.11.21/api/set?psm=2', { timeout: 2000, responseType: 'text' }, async (err, response) => {
      });
      setState('0_userdata.0.go-e_V4.1P_V4' /* 1P_V4 */, false);
      setState('0_userdata.0.go-e_V4.3P_V4' /* 3P_V4 */, true);
      setState('go-e.1.amperePV' /* Ampere for PWM (amx) (FW > 033 required) */, parseFloat(getState('0_userdata.0.go-e_V4.minA_3P_V4').val));
      if (getState('0_userdata.0.go-e_V4.minPV_V4').val > 4000) {
        setState('0_userdata.0.go-e_V4.minPV_V4' /* minPVÜberschuss_V4 */, 4000);
      }
      await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), 'Phasen / -------->>> Umschaltung auf 3P');
      sendTo('telegram.0', 'send', {
        text: 'go-ECharger V4 auf 3P Ladung umgeschaltet',
      });
      console.log('telegram: ' + 'go-ECharger V4 auf 3P Ladung umgeschaltet');
    }
    // Kontrolle min.PV
    if (getState('0_userdata.0.go-e_V4.1P_V4').val && getState('0_userdata.0.go-e_V4.minPV_V4').val > 2000) {
      setState('0_userdata.0.go-e_V4.minPV_V4' /* minPVÜberschuss_V4 */, 1250);
    }
  }
});


